const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');
const express = require('express');

const app = express();
app.use(express.static('/app'));

const server = app.listen(3000, async () => {
  console.log('Server started on port 3000');

  try {
    const browser = await puppeteer.launch({
      args: ['--no-sandbox', '--disable-setuid-sandbox']
    });
    const page = await browser.newPage();
    await page.setViewport({ width: 1200, height: 1800, deviceScaleFactor: 2 });

    await page.goto('http://localhost:3000/poster.html', { waitUntil: 'networkidle0' });

    // Give it an extra second to ensure fonts and canvas are fully rendered
    await new Promise(r => setTimeout(r, 2000));

    // Ensure output directory exists
    if (!fs.existsSync('/app/output')) {
      fs.mkdirSync('/app/output', { recursive: true });
    }

    await page.screenshot({ path: '/app/output/final_poster.png' });

    await browser.close();
    console.log('Screenshot saved to /app/output/final_poster.png');
  } catch (error) {
    console.error('Error generating screenshot:', error);
  } finally {
    server.close();
  }
});

